import React, { useEffect, useMemo, useState } from "react";
import ExampleWithLocalizationProvider from "../Components/Table";
import { catlogData } from "../../TableData";
import { Box } from "@mui/material";

function Catalog() {
  const [showData, setShowData] = useState([]);
  const [showDialog, setShowDialog] = useState(false);

  const catalogTable = useMemo(
    () => [
      {
        accessorKey: "id",
        header: "ID",
        size: 100,
      },
      {
        accessorKey: "userId",
        header: "User ID",
        size: 150,
      },
      {
        accessorKey: "amount",
        header: "Amount",
        size: 120,
        Cell: ({ cell }) => `$${cell.getValue()?.toFixed(2)}`, // format as currency
      },
      {
        accessorFn: (row) => `${row.firstName} ${row.lastName}`, // accessorFn used to join multiple data into a single cell
        id: "name", // id is still required when using accessorFn instead of accessorKey
        header: "Name",
        size: 250,
        Cell: ({ renderedCellValue, row }) => (
          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              gap: "1rem",
            }}
          >
            {/* using renderedCellValue instead of cell.getValue() preserves filter match highlighting */}
            <span>{renderedCellValue}</span>
          </Box>
        ),
      },
      {
        accessorFn: (row) => new Date(row.startDate), // convert to Date for sorting and filtering
        id: "startDate",
        header: "Start Date",
        filterVariant: "date",
        filterFn: "lessThan",
        sortingFn: "datetime",
        Cell: ({ cell }) => cell.getValue()?.toLocaleDateString(), // render Date as a string
        Header: ({ column }) => <em>{column.columnDef.header}</em>, // custom header markup
        muiFilterTextFieldProps: {
          sx: {
            minWidth: "250px",
          },
        },
      },
      {
        accessorKey: "createdBy", // accessorKey used to define `data` column. `id` gets set to accessorKey automatically
        enableClickToCopy: true,
        filterVariant: "autocomplete",
        header: "Created By",
        size: 300,
      },

      {
        accessorKey: "description", // hey a simple column for once
        header: "Description",
        size: 350,
      },
    ],
    []
  );

  useEffect(() => {
    // if (showData.length < 0)
    fetchData();
  }, []);

  async function fetchData() {
    try {
      const response = await fetch(catlogData, {
        method: "GET",
      });

      const data = await response.json();
      setShowData(data);
      console.log("get data ", data);

      return data;
    } catch (e) {
      setShowData([]);
      // console.error("Can't get data:", e);
    }
  }
  return (
    <ExampleWithLocalizationProvider
      columns={catalogTable}
      isCatalog={true}
      data={catlogData}
    />
  );
}

export default Catalog;
